import { test } from 'node:test';
import assert from 'node:assert/strict';
import { deployEmServidores, healthCheckOk } from './solution.mjs';

test('monta o comando de start com a porta do ambiente', () => {
  assert.equal(deployEmServidores({ script: 'server.mjs', port: 3000 }), 'PORT=3000 node server.mjs');
});

test('lança erro quando falta script ou port', () => {
  assert.throws(() => deployEmServidores({ script: 'server.mjs' }), /obrigatórios/);
  assert.throws(() => deployEmServidores({ port: 3000 }), /obrigatórios/);
});

test('healthCheckOk devolve true para status 200', () => {
  assert.equal(healthCheckOk(200), true);
});

test('healthCheckOk devolve false para outros status', () => {
  assert.equal(healthCheckOk(404), false);
  assert.equal(healthCheckOk(500), false);
});

solutionCode:
export function deployEmServidores(config) {
  const script = config && config.script;
  const port = config && config.port;
  if (typeof script !== 'string' || script === '' || typeof port !== 'number') {
    throw new Error('config inválido: script e port são obrigatórios');
  }
  return `PORT=${port} node ${script}`;
}

export function healthCheckOk(status) {
  return status === 200;
}
